    // ---------- 判定统一口径 ----------

    @Test
    void status_dueJudgmentUnifiedInMinutes() throws Exception {
        // HOURS 设备，周期 2 小时 = 120 分钟
        registerHours("eq-due", "2");
        postJson("/api/equipment/eq-due/readings", """
                {"requestId":"due-1","expectedVersion":1,"readingId":"r1",
